def frequency(lst):
    d={}
    for x in lst:
        d[x]=d.get(x,0)+1
    return d

def get_int(prompt):
    while True:
        try:
            return int(input(prompt))
        except ValueError:
            print('请输入整数')

def wc(filename):
    with open(filename) as f:
        text=f.read()
    return len(text.split('\n')),len(text.split()),len(text)

